{
  "application": "report-generation",
  "case_id": "case-global-fuel-prices-environment-en",
  "language": "en",
  "report": {
    "type": "trend-analysis",
    "audience": "policy analyst",
    "tone": "analytical, data-forward, professional"
  },
  "brief": {
    "title": "Global Fuel Price Trends & Policy Impact Analysis (2020–2026)",
    "one_liner": "A comprehensive trend analysis of retail fuel prices across 84 countries, examining the interplay between Brent Crude benchmarks, taxation, subsidies, and regional economic conditions over a six-year period.",
    "goal": "Equip energy policy analysts with a clear understanding of how global crude oil price movements translate into retail fuel costs across different regions, income levels, and subsidy regimes — and identify where policy interventions have been most and least effective at stabilizing consumer prices.",
    "required_sections": [
      {
        "section_id": "global-overview",
        "title": "Global Fuel Price Overview",
        "objective": "Present high-level summary statistics for petrol, diesel, and LPG prices across the full 2020–2026 period, including overall averages, ranges, and the trajectory of Brent Crude as a baseline."
      },
      {
        "section_id": "temporal-trends",
        "title": "Temporal Price Trends & Volatility",
        "objective": "Analyze weekly and yearly price trends for each fuel type, identify periods of peak volatility (e.g., COVID-19 demand shock, 2022 energy crisis), and quantify the correlation between Brent Crude movements and retail price changes."
      },
      {
        "section_id": "regional-comparison",
        "title": "Regional Price Disparities",
        "objective": "Compare average fuel prices across the seven geographic regions, highlighting which regions consistently pay the most and least, and how regional spreads have evolved over time."
      },
      {
        "section_id": "subsidy-tax-analysis",
        "title": "Impact of Subsidies and Taxation on Retail Prices",
        "objective": "Evaluate how subsidy levels (High vs. Low) and tax percentages influence the retail price consumers pay, segmented by income level. Assess whether high-subsidy countries show lower price pass-through from crude oil fluctuations."
      },
      {
        "section_id": "income-level-segmentation",
        "title": "Fuel Affordability by Income Level",
        "objective": "Segment countries by income classification (High, Middle, Low) and analyze differences in fuel pricing, tax burden, and price stability to draw conclusions about energy equity."
      },
      {
        "section_id": "key-findings-recommendations",
        "title": "Key Findings & Policy Implications",
        "objective": "Synthesize the most important insights from the analysis into actionable findings, including recommendations for policymakers on subsidy design, tax calibration, and price stabilization mechanisms."
      }
    ],
    "kpis": [
      {
        "name": "Average Retail Petrol Price (USD/Liter)",
        "description": "The mean petrol price across all countries and weeks, used as the primary benchmark for global fuel cost."
      },
      {
        "name": "Brent-to-Retail Price Correlation",
        "description": "Pearson correlation coefficient between weekly Brent Crude prices and retail petrol/diesel prices, measuring how tightly global benchmarks drive local costs."
      },
      {
        "name": "Subsidy Price Dampening Effect",
        "description": "The percentage difference in average retail fuel price between High-subsidy and Low-subsidy countries, quantifying the impact of government intervention."
      },
      {
        "name": "Regional Price Spread",
        "description": "The difference between the highest and lowest regional average petrol price in a given year, indicating global pricing inequality."
      },
      {
        "name": "Tax-to-Price Ratio by Income Level",
        "description": "Average tax percentage segmented by income level, revealing how fiscal policy on fuel varies with national wealth."
      }
    ],
    "analysis_dimensions": [
      "region",
      "income_level",
      "subsidy_level",
      "date",
      "tax_percentage"
    ]
  }
}

